+++ b/src/features/agenda.js
@@ -0,0 +1,14 @@
+import { createEventCard } from "./event-card.js";
+
+export function sortEventsChronologically(events) {
+  if (!Array.isArray(events)) {
+    throw new TypeError("Expected an array of events");
+  }
+  return events
+    .map((event, index) => ({ event, card: createEventCard(event), time: new Date(event.startsAt).getTime(), index }))
+    .sort((a, b) => a.time - b.time || a.index - b.index);
+}
+
+export function buildAgenda(events) {
+  return sortEventsChronologically(events).map(({ card }) => card);
+}

