+import { sortEventsChronologically } from "./agenda.js";
+import { summarizeAttendance } from "./attendance.js";
+
+function signupsFor(signupsByEvent, id) {
+  if (signupsByEvent != null && Object.prototype.hasOwnProperty.call(signupsByEvent, id)) {
+    return signupsByEvent[id] ?? [];
+  }
+  return [];
+}
+
+export function buildOrganizerDigest(events, signupsByEvent = {}) {
+  return sortEventsChronologically(events).map(({ event, card }) => ({
+    ...card,
+    ...summarizeAttendance(event, signupsFor(signupsByEvent, card.id)),
+  }));
+}

